W, H, N = map(int, input().split())

x_left = 0
x_right = W
y_low = 0
y_high = H

for _ in range(N):
    x, y, a = map(int, input().split())
    if a == 1:
        x_left = max(x_left, x)
    elif a == 2:
        x_right = min(x_right, x)
    elif a == 3:
        y_low = max(y_low, y)
    elif a == 4:
        y_high = min(y_high, y)

if x_right >= x_left and y_high >= y_low:
    area = (x_right - x_left) * (y_high - y_low)
else:
    area = 0

